SELECT upper(regexp_replace(trim(l.name),'\s+',' ','g')) norm_name,count(*) ledgers,string_agg(l.id||'='||l."groupId"||':'||g.name, ' || ' ORDER BY l.id) records FROM "Ledger" l LEFT JOIN "LedgerGroup" g ON g.id=l."groupId" WHERE l."branchId"='47fdc8aa-83ba-46f9-93ec-4517e0eb13bb' GROUP BY 1 HAVING count(*)>1 ORDER BY 1;
SELECT l.name,l.id,l.category,l."groupId",g.name group_name,count(e.id) entries,sum(CASE WHEN e."entryType"='DEBIT' THEN e.amount ELSE 0 END) debits,sum(CASE WHEN e."entryType"='CREDIT' THEN e.amount ELSE 0 END) credits FROM "Ledger" l LEFT JOIN "LedgerGroup" g ON g.id=l."groupId" LEFT JOIN "LedgerEntry" e ON e."ledgerId"=l.id WHERE l."branchId"='47fdc8aa-83ba-46f9-93ec-4517e0eb13bb' AND l.category='JOURNAL' GROUP BY l.id,g.name HAVING count(e.id)>0 ORDER BY l.name;
